report=json.loads((ROOT/'docs/artwork/course-art-audit.json').read_text());seen=set();groups=[]
for lesson in report['lessons']:
    words=[]
    for w in lesson['words']:
        if w['art'] is None and w['id'] not in seen:seen.add(w['id']);words.append(w)
    if not words:continue
    descriptions=scenes[lesson['number']];assert len(descriptions)==len(words),(lesson['number'],len(words),len(descriptions))
    for i,(w,scene)in enumerate(zip(words,descriptions)):w['scene']=scene;w['slot']=i;w['name']='course_'+w['id'].split('-')[-1]
    n=len(words);cols=1 if n==1 else 2 if n in (2,4) else 3;rows=(n+cols-1)//cols
    groups.append({'lesson':lesson['number'],'title':lesson['title'],'cols':cols,'rows':rows,'words':words,'status':'pending'})
assert len(seen)==208
(ROOT/'art-sources/course-completion-20261019/queue.json').write_text(json.dumps({'version':1,'count':208,'groups':groups},ensure_ascii=False,indent=2)+'\n')
